"""Printed 304–305: complete source Euler definitions/proof and examples 5–7."""
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
THEOREM_START=[heading('11.2 Euler’s Theorem'),paragraph('The specialty of Euler’s theorem is to verify the degree of a homogeneous function. The homogeneous function z=f(x,y) is not altered if the real numbers x and y of a function z=f(x,y) are stretched or squeezed by any real scalar quantity λ.'),heading('11.2.1 Homogeneous function of degree n'),paragraph('A function f(x,y) is said to be a homogeneous function of degree n if, for all values of λ and some constant value n, we have:'),eq(r'f(\lambda x,\lambda y)=\lambda^n f(x,y)','i'),paragraph('For example (a), f(x,y)=3x+4y is homogeneous of degree 1:'),eq(r'f(\lambda x,\lambda y)=3(\lambda x)+4(\lambda y)=\lambda(3x)+\lambda(4y)=\lambda(3x,4y)\quad\Rightarrow\quad f(\lambda x,\lambda y)=\lambda f(x,y)'),paragraph('(b) f(x,y)=3x²+4y² is homogeneous of degree 2:'),eq(r'f(\lambda x,\lambda y)=3(\lambda x)^2+4(\lambda y)^2=\lambda^2(3x^2,4y^2)\quad\Rightarrow\quad f(\lambda x,\lambda y)=\lambda^2f(x,y)'),paragraph('In general, a function f(x₁,x₂,x₃,…,xₙ) is homogeneous of degree n if for all λ and some constant n:'),eq(r'f(\lambda x_1,\lambda x_2,\ldots,\lambda x_n)=\lambda^n f(x_1,x_2,\ldots,x_n)'),heading('Remember'),paragraph('A function f(x,y) is homogeneous of degree n if it is expressed in the form:'),eq(r'f(x,y)=x^n f\left(\frac{y}{x}\right)'),heading('Example 5'),paragraph('Show that f(x,y)=2xy+y² is homogeneous of degree 2.'),heading('Solution'),paragraph('Verify the identity (i):'),eq(r'f(\lambda x,\lambda y)=2(\lambda x)(\lambda y)+(\lambda y)^2=2\lambda^2xy+\lambda^2y^2=\lambda^2(2xy+y^2)=\lambda^2f(x,y),\quad n=2'),paragraph('Thus the function is homogeneous of degree 2.'),heading('11.2.2 Verification of Euler’s theorem for homogeneous functions of different degrees'),paragraph('Statement: If z=f(x,y) is continuously differentiable and homogeneous of degree n, then:'),eq(r'x\frac{∂z}{∂x}+y\frac{∂z}{∂y}=nz','i'),paragraph('Proof: If z=xⁿf(y/x), its partial derivatives are:'),eq(r'\frac{∂z}{∂x}=\frac{∂}{∂x}x^n f\left(\frac{y}{x}\right)'),eq(r'\frac{∂z}{∂x}=nx^{n-1}f\left(\frac{y}{x}\right)+x^nf′\left(\frac{y}{x}\right)\left(-\frac{y}{x^2}\right)=nx^{n-1}f\left(\frac{y}{x}\right)-yx^{n-2}f′\left(\frac{y}{x}\right)','ii'),eq(r'\frac{∂z}{∂y}=x^nf′\left(\frac{y}{x}\right)\left(\frac1x\right)=x^{n-1}f′\left(\frac{y}{x}\right)','iii'),note('Homogeneity means values scale by λⁿ, rather than remaining unchanged unless n=0. Use positive λ and a domain preserved by that scaling when n is real; arbitrary negative λ or zero need not be meaningful. The commas in the two source expansions should be plus signs: λ(3x+4y) and λ²(3x²+4y²). In the many-variable formula, use m for the variable count and n for degree to avoid forcing them equal. The one-variable representation is z=xⁿg(y/x), using a new function g, locally on x>0 for general real degree; it is not a universal global formula across x=0.')]
THEOREM_END=[paragraph('Add equation (ii) multiplied by x and equation (iii) multiplied by y to obtain Euler’s method of order n:'),eq(r'x\frac{∂z}{∂x}+y\frac{∂z}{∂y}=x\left[nx^{n-1}f\left(\frac{y}{x}\right)-yx^{n-2}f′\left(\frac{y}{x}\right)\right]+y\left[x^{n-1}f′\left(\frac{y}{x}\right)\right]'),eq(r'=nx^nf\left(\frac{y}{x}\right)-yx^{n-1}f′\left(\frac{y}{x}\right)+yx^{n-1}f′\left(\frac{y}{x}\right)=nx^nf\left(\frac{y}{x}\right)=nz','iv'),note('A proof without dividing by x starts from f(λx,λy)=λⁿf(x,y) on an open scaling domain, differentiates with respect to λ, and sets λ=1: xfₓ+yfᵧ=nf. This covers regular points on x=0 as well. The theorem uses degree n, not derivative order n. For the zero function the identity holds for every n, so it does not determine a unique degree.')]
EX6=[heading('Example 6'),paragraph('Use Euler’s theorem to verify z=f(x,y)=ax²+2bxy+cy² is homogeneous of degree 2.'),heading('Solution'),paragraph('The homogeneous function and its derivatives are:'),eq(r'z=ax^2+2bxy+cy^2,\quad\frac{∂z}{∂x}=2ax+2by,\quad\frac{∂z}{∂y}=2bx+2cy'),paragraph('Use these in Euler’s result (iv):'),eq(r'x\frac{∂z}{∂x}+y\frac{∂z}{∂y}=x(2ax+2by)+y(2bx+2cy)=2ax^2+2bxy+2bxy+2cy^2=2(ax^2+2bxy+cy^2)=2z,\quad n=2'),paragraph('Euler’s procedure confirms second degree homogeneity.')]
EX7=[heading('Example 7'),paragraph('If u=tan⁻¹((x³+y³)/(x−y)), show xuₓ+yuᵧ=sin2u.'),heading('Solution'),paragraph('The function u is not homogeneous, but introduce a new variable z to obtain homogeneous form:'),eq(r'z=\tan u=\frac{x^3+y^3}{x-y}=\frac{x^3\left(1+(y/x)^3\right)}{x(1-y/x)}=x^2f\left(\frac{y}{x}\right)'),paragraph('This is homogeneous of degree 2. Euler’s theorem gives:'),eq(r'x\frac{∂z}{∂x}+y\frac{∂z}{∂y}=2z,\quad n=2','i'),paragraph('The partial derivatives of z=tan u are:'),eq(r'\frac{∂z}{∂x}=\sec^2u\frac{∂u}{∂x},\quad\frac{∂z}{∂y}=\sec^2u\frac{∂u}{∂y}'),paragraph('Substitute in (i):'),eq(r'\sec^2u\left(x\frac{∂u}{∂x}+y\frac{∂u}{∂y}\right)=2z,\quad z=\tan u'),eq(r'x\frac{∂u}{∂x}+y\frac{∂u}{∂y}=2z\cos^2u=2\frac{\sin u}{\cos u}\cos^2u=2\sin u\cos u=\sin2u'),note('Keep x≠y from the rational expression. For real principal arctangent, cos u≠0, so the chain-rule conversion is valid. Homogeneity applies to z=tan u rather than to u; an arctangent of a positive-degree homogeneous expression generally is not homogeneous. The source x²f(y/x) calculation is a chart with x≠0, but the rational function and Euler identity also apply at x=0,y≠0.')]
PAGES=[page('156_page_2.jpg',304,THEOREM_START),page('157_page_1.jpg',305,THEOREM_END+EX6+EX7)]
for p in PAGES:p.update(title='PARTIAL DIFFERENTIATION',visualStatus='Full native homogeneity scaling identities and Euler proof, all example calculations',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':(p['page']+9)//2,'side':'left' if p['page']%2 else 'right','reason':'All scaling exponents, chain-rule terms and proof cancellation visually checked'})
EXAMPLES=[]
for n,q,steps,ans,pg in [
('5','Show f(x,y)=2xy+y² is homogeneous of degree 2.',['Scale both inputs by λ: f(λx,λy)=2(λx)(λy)+(λy)².','Both terms gain exactly two factors of λ.','Thus f(λx,λy)=λ²(2xy+y²)=λ²f(x,y).','This is the defining identity with degree n=2.','It holds for every real λ for this polynomial, although positive scaling is sufficient for the usual real-domain definition.','As a check, fₓ=2y, fᵧ=2x+2y and xfₓ+yfᵧ=4xy+2y²=2f.'],'Homogeneous of degree 2.',304),
('6','Verify Euler’s theorem for z=ax²+2bxy+cy².',['Treat a,b,c as constants. Scaling x,y by λ multiplies every degree-two term by λ².','Differentiate with y fixed: zₓ=2ax+2by.','Differentiate with x fixed: zᵧ=2bx+2cy.','Multiply: xzₓ=2ax²+2bxy and yzᵧ=2bxy+2cy².','Add: xzₓ+yzᵧ=2ax²+4bxy+2cy²=2z.','Hence Euler’s identity for degree 2 is verified. If all coefficients vanish, z=0 and the identity holds for every degree; degree 2 is still a valid scaling identity.'],'xzₓ+yzᵧ=2z.',305),
('7','For u=arctan((x³+y³)/(x−y)), show xuₓ+yuᵧ=sin2u.',['Require x≠y and put z=(x³+y³)/(x−y)=tan u.','Scaling x,y by λ multiplies the numerator by λ³ and denominator by λ, so z has degree 2.','Euler’s theorem gives xzₓ+yzᵧ=2z.','Differentiate z=tan u: zₓ=sec²u·uₓ and zᵧ=sec²u·uᵧ.','Substitute: sec²u(xuₓ+yuᵧ)=2tan u.','Multiply by cos²u: xuₓ+yuᵧ=2sin u cos u=sin2u.','For a direct chain-rule check, uₓ=zₓ/(1+z²), uᵧ=zᵧ/(1+z²), giving 2z/(1+z²)=sin2u.'],'xuₓ+yuᵧ=sin2u, x≠y.',305)]:
 EXAMPLES.append({'num':n,'title':'Homogeneity and Euler’s Theorem','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'jpg':f'{(pg+9)//2:03d}_page_{1 if pg%2 else 2}.jpg','verification':'Full source homogeneity and Euler identity checked'}]})
